-- =============================================================================
-- Planificadoc — esquema inicial para Supabase (PostgreSQL)
--
-- ⚠️ YA APLICADA en Supabase (y registrada en public.schema_migrations).
--    NO volver a ejecutarla: no usa IF NOT EXISTS y falla con
--    "relation ... already exists". Para cambios nuevos crear un archivo
--    20261025xxxxxx_xxx.sql y correr `pnpm db:push`.
--
-- Traducción de `drizzle/schema.ts` (dialecto MySQL/TiDB) a PostgreSQL.
-- Reglas de traducción aplicadas:
--   * INT AUTO_INCREMENT      -> integer GENERATED BY DEFAULT AS IDENTITY
--   * VARCHAR(n) / TEXT       -> varchar(n) / text  (se conservan largos)
--   * ENUM(...)               -> text + CHECK (evita tipos enum nativos para
--                                mantener la compatibilidad con drizzle text)
--   * TIMESTAMP DEFAULT NOW() -> timestamptz DEFAULT now()
--   * ON UPDATE CURRENT_TIMESTAMP -> trigger `set_updated_at()`
--   * Nombres de columnas camelCase se declaran ENTRE COMILLAS ("openId"),
--     porque en PostgreSQL los identificadores sin comillas se pliegan a
--     minúsculas y eso rompería el mapeo de Drizzle.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- Trigger genérico: replican el `onUpdateNow()` de MySQL.
-- -----------------------------------------------------------------------------
create or replace function public.set_updated_at()
returns trigger
language plpgsql
as $$
begin
  new."updatedAt" := now();
  return new;
end;
$$;

-- =============================================================================
-- 1. users — núcleo del flujo de autenticación
-- =============================================================================
create table if not exists public.users (
  id            integer generated by default as identity primary key,
  "openId"      varchar(64)  not null,
  "name"        text,
  "email"       varchar(320),
  "loginMethod" varchar(64),
  "role"        varchar(16)  not null default 'user',
  "createdAt"   timestamptz  not null default now(),
  "updatedAt"   timestamptz  not null default now(),
  "lastSignedIn" timestamptz not null default now(),
  constraint uq_users_open_id unique ("openId"),
  constraint ck_users_role check ("role" in ('user', 'admin'))
);

create trigger trg_users_updated_at
  before update on public.users
  for each row execute function public.set_updated_at();

-- =============================================================================
-- 2. subscriptions — historial de suscripciones (una activa a la vez por email)
-- =============================================================================
create table if not exists public.subscriptions (
  id                   integer generated by default as identity primary key,
  "email"              varchar(320) not null,
  "userId"             integer,
  "plan"               varchar(32)  not null default 'monthly',
  "status"             varchar(16)  not null default 'active',
  "amountPaid"         integer      not null,
  "transactionId"      varchar(64),
  "authorizationCode"  varchar(64),
  "startDate"          timestamptz  not null default now(),
  "endDate"            timestamptz  not null,
  "isPromo"            boolean      not null default false,
  "isRecurring"        boolean      not null default false,
  "isTrial"            boolean      not null default false,
  "trialPlan"          varchar(32),
  "cardTokenId"        integer,
  "failedChargeAttempts" integer    not null default 0,
  "lastChargeAttempt"  timestamptz,
  "createdAt"          timestamptz  not null default now(),
  constraint ck_subscriptions_status
    check ("status" in ('active', 'expired', 'cancelled', 'past_due', 'trial')),
  constraint ck_subscriptions_plan check ("plan" in ('monthly', 'anual'))
);

create index if not exists idx_subscriptions_email    on public.subscriptions ("email");
create index if not exists idx_subscriptions_user_id  on public.subscriptions ("userId");
create index if not exists idx_subscriptions_status   on public.subscriptions ("status");
create index if not exists idx_subscriptions_end_date on public.subscriptions ("endDate");

-- =============================================================================
-- 3. card_tokens — tokens de tarjeta para cobros recurrentes (PayPhone)
-- =============================================================================
create table if not exists public.card_tokens (
  id            integer generated by default as identity primary key,
  "email"       varchar(320)  not null,
  "cardToken"   varchar(255)  not null,
  "cardHolder"  varchar(255)  not null,
  "documentId"  varchar(20)   not null,
  "phoneNumber" varchar(20)   not null,
  "cardBrand"   varchar(64),
  "lastDigits"  varchar(8),
  "isActive"    boolean       not null default true,
  "createdAt"   timestamptz   not null default now(),
  "updatedAt"   timestamptz   not null default now()
);

create trigger trg_card_tokens_updated_at
  before update on public.card_tokens
  for each row execute function public.set_updated_at();

create index if not exists idx_card_tokens_email on public.card_tokens ("email");
create index if not exists idx_card_tokens_active on public.card_tokens ("email") where "isActive";

-- =============================================================================
-- 4. payment_transactions — log de intentos de pago PayPhone
-- =============================================================================
create table if not exists public.payment_transactions (
  id                     integer generated by default as identity primary key,
  "clientTransactionId"  varchar(64)  not null,
  "email"                varchar(320) not null,
  "amount"               integer      not null,
  "payphoneTransactionId" integer,
  "status"               varchar(16)  not null default 'pending',
  "statusCode"           integer,
  "authorizationCode"    varchar(64),
  "cardType"             varchar(32),
  "cardBrand"            varchar(128),
  "lastDigits"           varchar(8),
  "payphoneResponse"     text,
  "isRecurringCharge"    boolean      not null default false,
  "cardTokenId"          integer,
  "cardHolder"           varchar(255),
  "documentId"           varchar(20),
  "phoneNumber"          varchar(20),
  "plan"                 varchar(16),
  "createdAt"            timestamptz  not null default now(),
  "updatedAt"            timestamptz  not null default now(),
  constraint uq_payment_transactions_client_tx
    unique ("clientTransactionId"),
  constraint ck_payment_transactions_status
    check ("status" in ('pending', 'approved', 'cancelled', 'error'))
);

create trigger trg_payment_transactions_updated_at
  before update on public.payment_transactions
  for each row execute function public.set_updated_at();

create index if not exists idx_payment_transactions_email    on public.payment_transactions ("email");
create index if not exists idx_payment_transactions_created  on public.payment_transactions ("createdAt");
create index if not exists idx_payment_transactions_token_id on public.payment_transactions ("cardTokenId");

-- =============================================================================
-- 5. code_activations — activaciones de códigos (antisharing por dispositivo)
-- =============================================================================
create table if not exists public.code_activations (
  id          integer generated by default as identity primary key,
  "code"      varchar(64)  not null,
  "deviceId"  varchar(128) not null,
  "platform"  varchar(16),
  "email"     varchar(320),
  "ipAddress" varchar(64),
  "createdAt" timestamptz  not null default now()
);

create index if not exists idx_code_activations_code    on public.code_activations ("code");
create index if not exists idx_code_activations_device  on public.code_activations ("deviceId");
create index if not exists idx_code_activations_created on public.code_activations ("createdAt");

-- =============================================================================
-- 6. docente_accounts — login email + password (scrypt) de docentes
-- =============================================================================
create table if not exists public.docente_accounts (
  id           integer generated by default as identity primary key,
  "email"      varchar(320) not null,
  "nombre"     varchar(255) not null,
  "passwordHash" varchar(512) not null,
  "lastLoginAt"  timestamptz,
  "createdAt"  timestamptz  not null default now(),
  "updatedAt"  timestamptz  not null default now(),
  constraint uq_docente_accounts_email unique ("email")
);

create trigger trg_docente_accounts_updated_at
  before update on public.docente_accounts
  for each row execute function public.set_updated_at();

-- =============================================================================
-- 7. password_reset_codes — códigos de recuperación de contraseña (1 uso)
-- =============================================================================
create table if not exists public.password_reset_codes (
  id          integer generated by default as identity primary key,
  "email"     varchar(320) not null,
  "codeHash"  varchar(128) not null,
  "attempts"  integer      not null default 0,
  "expiresAt" timestamptz  not null,
  "sentAt"    timestamptz  not null
);

create index if not exists idx_password_reset_email on public.password_reset_codes ("email");

-- =============================================================================
-- 8. docente_contacts — contactos registrados por el admin al entregar códigos
-- =============================================================================
create table if not exists public.docente_contacts (
  id            integer generated by default as identity primary key,
  "code"        varchar(64)  not null,
  "nombre"      varchar(255) not null,
  "email"       varchar(320),
  "phoneNumber" varchar(20),
  "institucion" varchar(255),
  "pago"        boolean      not null default false,
  "montoCobrado" integer     not null default 0,
  "notas"       text,
  "createdAt"   timestamptz  not null default now()
);

create index if not exists idx_docente_contacts_code  on public.docente_contacts ("code");
create index if not exists idx_docente_contacts_email on public.docente_contacts ("email");

-- =============================================================================
-- 9. pca_documents — Planificación Curricular Anual generada con IA
-- =============================================================================
create table if not exists public.pca_documents (
  id                       integer generated by default as identity primary key,
  "sessionId"              varchar(320) not null,
  "status"                 varchar(16)  not null default 'draft',
  "formData"               text         not null,
  "aiResult"               text,
  "clientTransactionId"    varchar(64),
  "payphoneTransactionId"  integer,
  "authorizationCode"      varchar(64),
  "amountPaid"             integer,
  "createdAt"              timestamptz  not null default now(),
  "updatedAt"              timestamptz  not null default now(),
  constraint ck_pca_documents_status check ("status" in ('draft', 'generated', 'paid'))
);

create trigger trg_pca_documents_updated_at
  before update on public.pca_documents
  for each row execute function public.set_updated_at();

create index if not exists idx_pca_documents_session on public.pca_documents ("sessionId");
create index if not exists idx_pca_documents_client_tx on public.pca_documents ("clientTransactionId");

-- =============================================================================
-- 10. planificacion_stats — contador sincronizado desde el dispositivo
-- =============================================================================
create table if not exists public.planificacion_stats (
  id               integer generated by default as identity primary key,
  "identifier"     varchar(320) not null,
  "identifierType" varchar(16)  not null default 'email',
  "count"          integer      not null default 0,
  "platform"       varchar(16),
  "updatedAt"      timestamptz  not null default now(),
  "createdAt"      timestamptz  not null default now(),
  constraint uq_planificacion_stats_identifier unique ("identifier")
);

create trigger trg_planificacion_stats_updated_at
  before update on public.planificacion_stats
  for each row execute function public.set_updated_at();

-- =============================================================================
-- 11. curricular_adaptations — adaptaciones curriculares para estudiantes NEE
-- =============================================================================
create table if not exists public.curricular_adaptations (
  id                   integer generated by default as identity primary key,
  "sessionId"          varchar(320) not null,
  "codigoEstudiante"   varchar(64),
  "institucion"        varchar(255),
  "docente"            varchar(255),
  "anioLectivo"        varchar(20),
  "area"               varchar(20)  not null,
  "subnivel"           integer,
  "grado"              varchar(64)  not null,
  "paralelo"           varchar(20),
  "periodoPedagogico"  varchar(64),
  "trimestre"          varchar(20),
  "codigoDestreza"     varchar(64),
  "descripcionDestreza" text,
  "gradoAdaptacion"    varchar(4)   not null,
  "tipoNEE"            varchar(64)  not null,
  "estiloAprendizaje"  varchar(64),
  "fortalezas"         text,
  "desafios"           text,
  "apoyosDisponibles"  text,
  "aiResult"           text,
  "version"            integer      not null default 1,
  "status"             varchar(16)  not null default 'draft',
  "createdAt"          timestamptz  not null default now(),
  "updatedAt"          timestamptz  not null default now(),
  constraint ck_curricular_adaptations_grado_adaptacion
    check ("gradoAdaptacion" in ('1', '2', '3')),
  constraint ck_curricular_adaptations_status
    check ("status" in ('draft', 'generated'))
);

create trigger trg_curricular_adaptations_updated_at
  before update on public.curricular_adaptations
  for each row execute function public.set_updated_at();

create index if not exists idx_curricular_adaptations_session on public.curricular_adaptations ("sessionId");
create index if not exists idx_curricular_adaptations_grado   on public.curricular_adaptations ("grado");

-- =============================================================================
-- 12. dcd_desagregaciones — gradación de DCD por grado (respaldo best-effort)
-- =============================================================================
create table if not exists public.dcd_desagregaciones (
  id                  integer generated by default as identity primary key,
  "sessionId"         varchar(320) not null,
  "codigoDCD"         varchar(64)  not null,
  "subnivel"          integer      not null,
  "grado"             integer      not null,
  "gradoMaximo"       integer      not null,
  "descripcionDCD"    text         not null,
  "indicadorOriginal" text         not null,
  "dcdGraduada"       text         not null,
  "indicadorGraduado" text         not null,
  "procesoCognitivo"  varchar(128),
  "estado"            varchar(16)  not null default 'generado',
  "version"           integer      not null default 1,
  "aiResult"          text,
  "createdAt"         timestamptz  not null default now(),
  "updatedAt"         timestamptz  not null default now(),
  constraint uq_dcd_session_grado
    unique ("sessionId", "codigoDCD", "grado"),
  constraint ck_dcd_desagregaciones_estado
    check ("estado" in ('generado', 'editado', 'aprobado'))
);

create trigger trg_dcd_desagregaciones_updated_at
  before update on public.dcd_desagregaciones
  for each row execute function public.set_updated_at();

create index if not exists idx_dcd_session on public.dcd_desagregaciones ("sessionId");
create index if not exists idx_dcd_codigo  on public.dcd_desagregaciones ("codigoDCD");
create index if not exists idx_dcd_created on public.dcd_desagregaciones ("createdAt");

-- =============================================================================
-- 13. connecta_nivela_crea — planes CNC (5 semanas de arranque, MinEduc)
-- =============================================================================
create table if not exists public.connecta_nivela_crea (
  id                    integer generated by default as identity primary key,
  "sessionId"           varchar(320) not null,
  "institucion"         varchar(255),
  "docente"             varchar(255),
  "anioLectivo"         varchar(20),
  "grado"               varchar(64),
  "paralelo"            varchar(20),
  "subnivel"            varchar(64),
  "modalidad"           varchar(16)  not null default 'general',
  "figuraProfesionalId" varchar(64),
  "moduloId"            varchar(64),
  "form"                text,
  "aiResult"            text,
  "status"              varchar(16)  not null default 'draft',
  "createdAt"           timestamptz  not null default now(),
  "updatedAt"           timestamptz  not null default now(),
  constraint ck_connecta_nivela_crea_modalidad check ("modalidad" in ('general', 'bt')),
  constraint ck_connecta_nivela_crea_status     check ("status" in ('draft', 'generated'))
);

create trigger trg_connecta_nivela_crea_updated_at
  before update on public.connecta_nivela_crea
  for each row execute function public.set_updated_at();

create index if not exists idx_connecta_session    on public.connecta_nivela_crea ("sessionId");
create index if not exists idx_connecta_modalidad  on public.connecta_nivela_crea ("modalidad");
create index if not exists idx_connecta_created    on public.connecta_nivela_crea ("createdAt");

-- =============================================================================
-- 14. evaluaciones_diagnosticas — evaluaciones diagnósticas (respaldo en la nube)
-- =============================================================================
create table if not exists public.evaluaciones_diagnosticas (
  id          integer generated by default as identity primary key,
  "sessionId" varchar(320) not null,
  "status"    varchar(16)  not null default 'borrador',
  "form"      text,
  "aiResult"  text,
  "createdAt" timestamptz  not null default now(),
  "updatedAt" timestamptz  not null default now(),
  constraint ck_evaluaciones_diagnosticas_status
    check ("status" in ('borrador', 'publicada', 'aplicada', 'analizada'))
);

create trigger trg_evaluaciones_diagnosticas_updated_at
  before update on public.evaluaciones_diagnosticas
  for each row execute function public.set_updated_at();

create index if not exists idx_evaluaciones_session on public.evaluaciones_diagnosticas ("sessionId");
create index if not exists idx_evaluaciones_status  on public.evaluaciones_diagnosticas ("status");
create index if not exists idx_evaluaciones_created on public.evaluaciones_diagnosticas ("createdAt");

-- =============================================================================
-- 15. payment_attribution — señales Meta CAPI guardadas antes de PayPhone
--     (nombres snake_case tal como en el esquema original)
-- =============================================================================
create table if not exists public.payment_attribution (
  client_tx_id varchar(64)  primary key,
  event_id     varchar(64)  not null,
  value_cents  integer      not null,
  currency     varchar(8)   not null default 'USD',
  fbp          varchar(128),
  fbc          varchar(255),
  client_ip    varchar(64),
  user_agent   varchar(512),
  email        varchar(255),
  phone        varchar(32),
  user_id      varchar(64),
  source_url   varchar(512),
  sent         boolean      not null default false,
  created_at   timestamptz  default now()
);

create index if not exists idx_payment_attribution_event on public.payment_attribution (event_id);

-- =============================================================================
-- 16. curriculo_competencias_planificaciones — módulo Currículo por Competencias
-- =============================================================================
create table if not exists public.curriculo_competencias_planificaciones (
  id                    integer generated by default as identity primary key,
  session_id            varchar(64)  not null,
  tipo                  varchar(24)  not null,
  grado                 varchar(32),
  institucion           varchar(128),
  docente               varchar(128),
  paralelo              varchar(16),
  asignatura            varchar(64),
  nivel                 varchar(8),
  periodo_pedagogico    varchar(64),
  trimestre             varchar(32),
  dcd_codigo            varchar(32),
  competencias          text,
  status                varchar(16)  not null default 'draft',
  hay_nee               boolean      not null default false,
  compartida            boolean      not null default false,
  form_data             text         not null,
  ai_result             text,
  source_traceability   text,
  created_at            timestamptz  not null default now(),
  updated_at            timestamptz  not null default now(),
  constraint ck_cc_plan_tipo   check (tipo in ('egb_bgu', 'inicial_preparatoria')),
  constraint ck_cc_plan_nivel  check (nivel is null or nivel in ('EGB', 'BGU')),
  constraint ck_cc_plan_status check (status in ('draft', 'generated', 'paid'))
);

-- `updated_at` se mantiene desde la aplicación (mismo comportamiento que en
-- MySQL vía ON UPDATE), por lo que no se le asigna trigger aquí para no
-- duplicar la escritura en los routers que ya lo hacen.

create index if not exists idx_cc_plan_session  on public.curriculo_competencias_planificaciones (session_id);
create index if not exists idx_cc_plan_grado    on public.curriculo_competencias_planificaciones (grado);
create index if not exists idx_cc_plan_status   on public.curriculo_competencias_planificaciones (status);
create index if not exists idx_cc_plan_created  on public.curriculo_competencias_planificaciones (created_at);

-- =============================================================================
-- 17. proyectos_interdisciplinares — módulo Proyecto Interdisciplinar
-- =============================================================================
create table if not exists public.proyectos_interdisciplinares (
  id                  integer generated by default as identity primary key,
  session_id          varchar(64)  not null,
  base_curricular     varchar(16)  not null,
  titulo              varchar(256) not null,
  nivel_principal     varchar(32),
  subnivel_principal  varchar(32),
  institucion         varchar(128),
  estado              varchar(16)  not null default 'borrador',
  form_data           text         not null,
  created_at          timestamptz  not null default now(),
  updated_at          timestamptz  not null default now(),
  constraint ck_proyectos_base_curricular
    check (base_curricular in ('destrezas', 'competencias')),
  constraint ck_proyectos_estado
    check (estado in ('borrador', 'generado'))
);

create index if not exists idx_proyectos_session on public.proyectos_interdisciplinares (session_id);
create index if not exists idx_proyectos_estado  on public.proyectos_interdisciplinares (estado);
create index if not exists idx_proyectos_created on public.proyectos_interdisciplinares (created_at);
